-- Theca schema. Single migration, rewritten in place until the first release.
--
-- Conventions: every table has a bigint identity `pk` (internal, used by FKs)
-- and a `uuid` (UUIDv7, generated by Postgres 18's uuidv7(), the only ID exposed).
-- Exception: `setting`, keyed by its name.
--
-- Closed lists are `text` + `CHECK` (no Postgres enums): plain strings for sqlx,
-- converted to Rust enums in one place; lists change by replacing the CHECK.
--
-- Each table is preceded by the line it was written from.
-- NOTE lines mark choices made while translating, to discuss.
-- TRIGGER lines mark invariants a constraint can't express; the triggers are at the end of the file.

CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- Name rules (docs/decisions.md, File names), mirrored from theca_common::name:
-- the code validates first (clear errors), the database refuses anything that
-- slips through.
CREATE FUNCTION is_valid_name(n text) RETURNS boolean
LANGUAGE sql IMMUTABLE STRICT AS $$
    SELECT n IS NFC NORMALIZED
       AND n <> ''
       AND octet_length(n) <= 255
       AND n !~ '[<>:"/\\|?*\x01-\x1f\u202a-\u202e\u2066-\u2069]'
       AND n !~ '[ .]$'
       AND upper(split_part(n, '.', 1)) NOT IN (
           'CON', 'PRN', 'AUX', 'NUL',
           'COM1', 'COM2', 'COM3', 'COM4', 'COM5', 'COM6', 'COM7', 'COM8', 'COM9',
           'LPT1', 'LPT2', 'LPT3', 'LPT4', 'LPT5', 'LPT6', 'LPT7', 'LPT8', 'LPT9'
       )
$$;

-- storage : organization nullable, is default unique where true, name, implementation (string), details json
CREATE TABLE storage (
    pk bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    uuid uuid NOT NULL UNIQUE DEFAULT uuidv7(),
    -- NULL: shared by the instance. Set: reserved to that organization.
    -- TRIGGER: can't change once set.
    organization bigint,  -- FK added below (organization is created after storage)
    name text NOT NULL,
    implementation text NOT NULL,
    details jsonb NOT NULL,
    is_default boolean NOT NULL DEFAULT false
);
CREATE UNIQUE INDEX storage_one_default ON storage (is_default) WHERE is_default;
-- Shared storages (NULL organization) share one namespace.
CREATE UNIQUE INDEX storage_name ON storage (organization, lower(name)) NULLS NOT DISTINCT;

-- organization : name, fk default storage, owner (composite FK user(org, pk))
CREATE TABLE organization (
    pk bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    uuid uuid NOT NULL UNIQUE DEFAULT uuidv7(),
    name text NOT NULL,
    -- TRIGGER: the default storage is shared (NULL) or belongs to this organization.
    default_storage bigint REFERENCES storage,
    -- Composite FK added below (cycle with "user"). NULL only once deleted.
    owner bigint,
    -- Storage quota in bytes (sum of the stored sizes of its chunks). NULL: unlimited.
    quota bigint CONSTRAINT organization_quota CHECK (quota >= 0),
    -- Constant, only for the owner FK below: the owner has joined (not an invitation).
    owner_joined boolean NOT NULL DEFAULT true CHECK (owner_joined),
    -- Personal organization of this account ("My files"; created at
    -- self-registration and OIDC sign-up), NULL for a company one. Its owner is
    -- that account (FK below), and it never has another member (trigger).
    personal_of bigint UNIQUE,  -- FK to account added below (account is created after)
    -- Suspended (e.g. unpaid): nothing of it is reachable (organization_access);
    -- its members still log in and see it suspended.
    suspended_at timestamptz,
    -- Deleted: its data is gone, its chunks tombstoned; the row stays (chunks
    -- reference it until the GC has deleted their objects), then goes.
    deleted_at timestamptz,
    CONSTRAINT organization_owner_present CHECK (owner IS NOT NULL OR deleted_at IS NOT NULL)
);

ALTER TABLE storage
    ADD FOREIGN KEY (organization) REFERENCES organization;

-- account : email, instance_admin, verified, created_at
-- NOTE: email unique ignoring case.
CREATE TABLE account (
    pk bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    uuid uuid NOT NULL UNIQUE DEFAULT uuidv7(),
    email text NOT NULL,
    instance_admin boolean NOT NULL DEFAULT false,
    verified boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(),
    -- Suspended (abuse): its tokens stop authenticating, it can't log in.
    suspended_at timestamptz
);
CREATE UNIQUE INDEX account_email ON account (lower(email));

-- identity_provider : OIDC providers. Instance-wide (organization NULL,
-- configured by the instance admin) or an organization's. A provider can assert
-- any subject or email, so trust follows who controls it: logging in through an
-- organization's provider opens a session restricted to that organization.
CREATE TABLE identity_provider (
    pk bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    uuid uuid NOT NULL UNIQUE DEFAULT uuidv7(),
    organization bigint REFERENCES organization ON DELETE CASCADE,
    name text NOT NULL,         -- shown on the login screen
    issuer text NOT NULL,       -- discovery: <issuer>/.well-known/openid-configuration
    client_id text NOT NULL,
    -- The client secret: a path (instance-wide providers, configured by the
    -- instance admin), or the value encrypted with the DATA_KEY__FILE key (an
    -- organization's: a path chosen by an organization's owner would read any
    -- server file and send it to their own provider).
    client_secret_file text,
    client_secret_encrypted text,
    enabled boolean NOT NULL DEFAULT true,
    CONSTRAINT identity_provider_secret CHECK ((client_secret_file IS NULL) <> (client_secret_encrypted IS NULL)),
    CONSTRAINT identity_provider_secret_file CHECK (organization IS NULL OR client_secret_file IS NULL)
);
CREATE UNIQUE INDEX identity_provider_name ON identity_provider (organization, lower(name)) NULLS NOT DISTINCT;

-- identity : how an account logs in.
--   password: details.hash (Argon2id PHC string)
--   oidc:     provider + details.subject
--   totp:     second factor of the password: details.secret (encrypted with the
--             DATA_KEY__FILE key, the account as associated data), details.confirmed
--             (required at login once a first code was given), details.last_step
--             (the last time step used: codes can't be replayed)
CREATE TABLE identity (
    pk bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    uuid uuid NOT NULL UNIQUE DEFAULT uuidv7(),
    account bigint NOT NULL REFERENCES account ON DELETE CASCADE,
    kind text NOT NULL CHECK (kind IN ('password', 'oidc', 'totp')),
    provider bigint REFERENCES identity_provider ON DELETE CASCADE,
    -- Kind-specific data; each kind's required keys are checked below.
    -- IS NOT DISTINCT FROM: a missing key gives NULL, and a CHECK evaluating to NULL passes.
    details jsonb NOT NULL,
    CONSTRAINT identity_provider_oidc CHECK ((kind = 'oidc') = (provider IS NOT NULL)),
    CONSTRAINT identity_password_details CHECK (kind <> 'password' OR jsonb_typeof(details->'hash') IS NOT DISTINCT FROM 'string'),
    CONSTRAINT identity_oidc_details CHECK (kind <> 'oidc' OR jsonb_typeof(details->'subject') IS NOT DISTINCT FROM 'string'),
    CONSTRAINT identity_totp_details CHECK (kind <> 'totp' OR (
        jsonb_typeof(details->'secret') IS NOT DISTINCT FROM 'string'
        AND jsonb_typeof(details->'confirmed') IS NOT DISTINCT FROM 'boolean'
        AND jsonb_typeof(details->'last_step') IS NOT DISTINCT FROM 'number'))
);
CREATE INDEX identity_account ON identity (account);
-- At most one password and one TOTP per account.
CREATE UNIQUE INDEX identity_password ON identity (account) WHERE kind = 'password';
CREATE UNIQUE INDEX identity_totp ON identity (account) WHERE kind = 'totp';
-- An external account (provider + subject) belongs to at most one account here.
CREATE UNIQUE INDEX identity_oidc ON identity (provider, (details->>'subject')) WHERE kind = 'oidc';

-- user : account, organization, joined_at (NULLABLE for invites) (unique(acc, org))
-- NOTE: "user" is a reserved word in Postgres: it must be quoted everywhere.
CREATE TABLE "user" (
    pk bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    uuid uuid NOT NULL UNIQUE DEFAULT uuidv7(),
    account bigint NOT NULL REFERENCES account,
    organization bigint NOT NULL REFERENCES organization,
    joined_at timestamptz,  -- NULL: invited, not yet accepted
    -- When an invitation was sent (pending invitations expire from it).
    invited_at timestamptz,
    joined boolean NOT NULL GENERATED ALWAYS AS (joined_at IS NOT NULL) STORED,
    UNIQUE (account, organization),
    -- Logically redundant with pk, but an FK target must be UNIQUE.
    UNIQUE (organization, pk),          -- target of "member of this organization" FKs
    UNIQUE (organization, pk, joined),  -- target of organization's owner FK
    UNIQUE (pk, account)                -- target of the personal organization's FK
);

-- The owner is a member of the organization who has joined: exactly one owner.
-- Deferred (checked at COMMIT): the code reserves the owner's pk with nextval(),
-- then inserts the organization and its owner (OVERRIDING SYSTEM VALUE) in one
-- transaction. The owner can't be removed nor un-joined while owner.
ALTER TABLE organization
    ADD CONSTRAINT organization_owner FOREIGN KEY (pk, owner, owner_joined) REFERENCES "user" (organization, pk, joined)
    DEFERRABLE INITIALLY DEFERRED,
    -- A personal organization's owner is its account (NULL personal_of: not checked).
    ADD CONSTRAINT organization_personal_owner FOREIGN KEY (owner, personal_of) REFERENCES "user" (pk, account)
    DEFERRABLE INITIALLY DEFERRED,
    ADD CONSTRAINT organization_personal_of FOREIGN KEY (personal_of) REFERENCES account;

-- library : name, owner, storage (nullable)
-- NOTE: UNIQUE (owner, lower(name)) from decisions.md (Library names).
CREATE TABLE library (
    pk bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    uuid uuid NOT NULL UNIQUE DEFAULT uuidv7(),
    name text NOT NULL,
    -- The organization owns the library: pays for it (quota) and keeps it when
    -- members leave. Who can access it: library_member.
    owner bigint NOT NULL REFERENCES organization,
    -- not nullable, or changing the default would make a part of the lib in one storage, then in another one
    -- TRIGGER: shared (NULL organization) or the library's organization's.
    storage bigint NOT NULL REFERENCES storage,
    -- In the trash (with everything in it: unreachable, see library_access);
    -- purged after the trash retention.
    deleted_at timestamptz,
    CONSTRAINT library_name_valid CHECK (is_valid_name(name)),
    UNIQUE (owner, pk)  -- target of composite FKs checking the organization
);
-- Names unique outside the trash.
CREATE UNIQUE INDEX library_name ON library (owner, lower(name)) WHERE deleted_at IS NULL;

-- library_member : who can access a library, with which rights.
-- A private library is a library with a single member. When a user is removed,
-- their memberships go (CASCADE); the libraries stay with the organization.
CREATE TABLE library_member (
    pk bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    uuid uuid NOT NULL UNIQUE DEFAULT uuidv7(),
    organization bigint NOT NULL,
    library bigint NOT NULL,
    "user" bigint NOT NULL,
    role text NOT NULL CHECK (role IN ('read', 'write')),
    UNIQUE (library, "user"),
    -- The library and the member belong to the same organization.
    CONSTRAINT library_member_library FOREIGN KEY (organization, library) REFERENCES library (owner, pk) ON DELETE CASCADE,
    CONSTRAINT library_member_user FOREIGN KEY (organization, "user") REFERENCES "user" (organization, pk) ON DELETE CASCADE
);
CREATE INDEX library_member_user ON library_member ("user");

-- token : usage, resource, prefix, hash, user_agent, ip, location, created_at, last_seen, revoked_at, revocation_reason
-- NOTE: resource is the target entity's uuid (no FK, by design).
CREATE TABLE token (
    pk bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    uuid uuid NOT NULL UNIQUE DEFAULT uuidv7(),
    usage text NOT NULL CHECK (usage IN (
        'session',
        'email_verification',
        'invitation',
        'password_reset',
        'app_password',
        'recovery_code'
    )),
    resource uuid NOT NULL,
    prefix text NOT NULL UNIQUE,
    hash bytea NOT NULL CHECK (length(hash) = 32),  -- SHA-256
    user_agent text,
    ip inet,
    location text,
    created_at timestamptz NOT NULL DEFAULT now(),
    last_seen timestamptz,
    revoked_at timestamptz,
    revocation_reason text,
    -- Shown in lists: given by the user (app passwords) or by the server.
    name text NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    -- Scope (see organization_access): a session opened through an
    -- organization's identity provider, or an app password limited to an
    -- organization, only acts on that organization (NULL: the whole account).
    organization bigint REFERENCES organization ON DELETE CASCADE,
    -- An app password limited to one library (of `organization`).
    library bigint,
    -- An app password that can only read (a cap on the membership's role).
    read_only boolean NOT NULL DEFAULT false,
    CONSTRAINT token_revocation_reason CHECK ((revoked_at IS NULL) = (revocation_reason IS NULL)),
    CONSTRAINT token_organization_scope CHECK (organization IS NULL OR usage IN ('session', 'app_password')),
    CONSTRAINT token_library_scope CHECK (library IS NULL OR (usage = 'app_password' AND organization IS NOT NULL)),
    CONSTRAINT token_read_only CHECK (NOT read_only OR usage = 'app_password'),
    CONSTRAINT token_library FOREIGN KEY (organization, library) REFERENCES library (owner, pk) ON DELETE CASCADE
);
CREATE INDEX token_resource ON token (resource);

-- Authorization: what a credential (a session or app password `token` row)
-- reaches. Every query that touches an organization's or a library's data joins
-- these; no access join is written by hand elsewhere (docs/decisions.md,
-- Authorization). Plain SQL functions: the planner inlines them.

-- The organizations a token acts in: the account's joined memberships, within
-- the token's scope, unless suspended. `library` is the token's library scope (NULL: every
-- library); `can_write` is false for read-only tokens. Revocation and expiry
-- are checked once per request, when the token is looked up.
CREATE FUNCTION organization_access(token bigint)
RETURNS TABLE (organization bigint, "user" bigint, library bigint, can_write boolean)
LANGUAGE sql STABLE AS $$
    SELECT u.organization, u.pk, t.library, NOT t.read_only
    FROM token t
    JOIN account a ON a.uuid = t.resource
    JOIN "user" u ON u.account = a.pk AND u.joined_at IS NOT NULL
    JOIN organization o ON o.pk = u.organization AND o.suspended_at IS NULL
    WHERE t.pk = $1 AND t.usage IN ('session', 'app_password')
      AND (t.organization IS NULL OR u.organization = t.organization)
$$;

-- The libraries a token reaches: library memberships within its scope.
-- `can_write`: the member's role is `write` and the token isn't read-only.
-- Trashed libraries included: only for the trash's own operations (list,
-- restore, purge).
CREATE FUNCTION library_access_any(token bigint)
RETURNS TABLE (library bigint, organization bigint, "user" bigint, can_write boolean)
LANGUAGE sql STABLE AS $$
    SELECT m.library, o.organization, o."user", o.can_write AND m.role = 'write'
    FROM organization_access($1) o
    JOIN library_member m ON m."user" = o."user"
    WHERE o.library IS NULL OR m.library = o.library
$$;

-- What every other query joins: a trashed library and everything in it are
-- out of reach.
CREATE FUNCTION library_access(token bigint)
RETURNS TABLE (library bigint, organization bigint, "user" bigint, can_write boolean)
LANGUAGE sql STABLE AS $$
    SELECT a.* FROM library_access_any($1) a
    JOIN library l ON l.pk = a.library
    WHERE l.deleted_at IS NULL
$$;

-- namespace : a dedup boundary, owned by an organization. Libraries in a common
-- namespace declare that all their members trust each other: an upload into a
-- library dedups against the chunks of every library sharing a namespace with
-- it, and against the library itself (always, even with no namespace).
--
-- A namespace stores no chunks: a chunk is known to a namespace when a version
-- of a library currently in it references the chunk. The lookup computes this
-- at upload time, so adding or removing a library takes effect immediately
-- (removing it revokes the trust: its chunks can't be probed through the
-- namespace anymore). Pending chunks (not yet in a version) only match within
-- the library they were uploaded into.
CREATE TABLE namespace (
    pk bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    uuid uuid NOT NULL UNIQUE DEFAULT uuidv7(),
    organization bigint NOT NULL REFERENCES organization,
    name text NOT NULL,
    UNIQUE (organization, pk)
);
CREATE UNIQUE INDEX namespace_name ON namespace (organization, lower(name));

-- library_namespace : a library can be in several namespaces (or none).
CREATE TABLE library_namespace (
    pk bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    uuid uuid NOT NULL UNIQUE DEFAULT uuidv7(),
    organization bigint NOT NULL,
    library bigint NOT NULL,
    namespace bigint NOT NULL,
    UNIQUE (library, namespace),
    -- Library and namespace belong to the same organization: dedup never
    -- crosses organizations (nor, therefore, their storages).
    CONSTRAINT library_namespace_library FOREIGN KEY (organization, library) REFERENCES library (owner, pk) ON DELETE CASCADE,
    CONSTRAINT library_namespace_namespace FOREIGN KEY (organization, namespace) REFERENCES namespace (organization, pk) ON DELETE CASCADE
);
CREATE INDEX library_namespace_namespace ON library_namespace (namespace);

-- node : library, parent (NULL), name, is_file, current_version (NULL), deleted_at
CREATE TABLE node (
    pk bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    uuid uuid NOT NULL UNIQUE DEFAULT uuidv7(),
    -- Carried down from the library (node, version, chunk_in_version) so composite
    -- FKs can guarantee a version never references another organization's chunk.
    organization bigint NOT NULL,
    library bigint NOT NULL,
    parent bigint,
    -- Constant, only for the composite FK below: the parent is a folder.
    parent_is_file boolean NOT NULL DEFAULT false CHECK (NOT parent_is_file),
    name text NOT NULL,
    is_file boolean NOT NULL,
    current_version bigint,  -- FK added below (cycle with version)
    deleted_at timestamptz,
    -- TRIGGER: moving a folder never makes it its own ancestor (end of file).
    -- The shortest cycle, also as a CHECK.
    CONSTRAINT node_not_own_parent CHECK (parent IS NULL OR parent <> pk),
    CONSTRAINT node_folder_has_no_version CHECK (is_file OR current_version IS NULL),
    -- Only the root has no parent; it's an unnamed folder, every other name is valid.
    CONSTRAINT node_root_unnamed CHECK ((parent IS NULL) = (name = '')),
    CONSTRAINT node_root_is_folder CHECK (parent IS NOT NULL OR NOT is_file),
    CONSTRAINT node_name_valid CHECK (parent IS NULL OR is_valid_name(name)),
    UNIQUE (organization, pk, is_file),  -- target of version's "file of this organization" FK
    UNIQUE (pk, library, is_file),       -- target of the "parent is a folder of the same library" FK
    CONSTRAINT node_library FOREIGN KEY (organization, library) REFERENCES library (owner, pk),
    -- The parent is a folder of the same library (NULL parent: root, not checked).
    -- A node's library changing (a move to another library) cascades to its
    -- subtree.
    CONSTRAINT node_parent FOREIGN KEY (parent, library, parent_is_file) REFERENCES node (pk, library, is_file)
        ON UPDATE CASCADE
);
CREATE UNIQUE INDEX node_name ON node (parent, lower(name)) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX node_one_root ON node (library) WHERE parent IS NULL;
CREATE INDEX node_name_search ON node USING gin (name gin_trgm_ops);
-- Walking down a subtree (copies, moves, hard deletion), trashed children included.
CREATE INDEX node_parent_all ON node (parent);
-- A library's trash.
CREATE INDEX node_trash ON node (library) WHERE deleted_at IS NOT NULL;

-- version : file, parent_version (composite FK?), message (nullable)
CREATE TABLE version (
    pk bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    uuid uuid NOT NULL UNIQUE DEFAULT uuidv7(),
    organization bigint NOT NULL,
    file bigint NOT NULL,
    -- Constant, only for the composite FK below: a version belongs to a file.
    file_is_file boolean NOT NULL DEFAULT true CHECK (file_is_file),
    parent_version bigint,
    message text,
    created_at timestamptz NOT NULL DEFAULT now(),
    -- Who committed it (a member of the organization); NULL once they leave.
    author bigint,
    UNIQUE (file, pk),
    UNIQUE (organization, pk),  -- target of chunk_in_version's FK
    CONSTRAINT version_file FOREIGN KEY (organization, file, file_is_file) REFERENCES node (organization, pk, is_file),
    -- The parent version is a version of the same file.
    CONSTRAINT version_parent FOREIGN KEY (file, parent_version) REFERENCES version (file, pk),
    CONSTRAINT version_author FOREIGN KEY (organization, author) REFERENCES "user" (organization, pk) ON DELETE SET NULL (author)
);
-- A file's history; a leaving member's versions (ON DELETE SET NULL).
CREATE INDEX version_by_file ON version (file);
CREATE INDEX version_by_author ON version (author);

-- Reachable: neither the node nor an ancestor is in the trash. Only the
-- trashed node itself is flagged (one row, whatever its subtree), so reads
-- climb to the root: one primary-key lookup per level.
CREATE FUNCTION node_reachable(node bigint) RETURNS boolean
LANGUAGE sql STABLE AS $$
    WITH RECURSIVE up (parent, deleted_at) AS (
        SELECT parent, deleted_at FROM node WHERE pk = $1
        UNION ALL
        SELECT n.parent, n.deleted_at FROM node n JOIN up ON n.pk = up.parent
    )
    SELECT NOT EXISTS (SELECT 1 FROM up WHERE deleted_at IS NOT NULL)
$$;

-- A node's path in its library: '/' for the root, '/a/b' below.
CREATE FUNCTION node_path(node bigint) RETURNS text
LANGUAGE sql STABLE AS $$
    WITH RECURSIVE up (parent, name, depth) AS (
        SELECT parent, name, 0 FROM node WHERE pk = $1
        UNION ALL
        SELECT n.parent, n.name, up.depth + 1 FROM node n JOIN up ON n.pk = up.parent
    )
    SELECT '/' || coalesce(string_agg(name, '/' ORDER BY depth DESC) FILTER (WHERE name <> ''), '')
    FROM up
$$;

-- The current version is a version of this node. Deferred: a file and its
-- first version are inserted in the same transaction.
ALTER TABLE node
    ADD CONSTRAINT node_current_version FOREIGN KEY (pk, current_version) REFERENCES version (file, pk)
    DEFERRABLE INITIALLY DEFERRED;

-- chunk : organization, library (origin), hash (16 bytes), storage, sizes, compression, stored_sha256, url_expires_at, uploaded_at, touched_at, deleting_at
CREATE TABLE chunk (
    pk bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    uuid uuid NOT NULL UNIQUE DEFAULT uuidv7(),
    -- Owner: billed for it (stored_size). Chunks never cross organizations.
    organization bigint NOT NULL REFERENCES organization,
    -- Library it was uploaded into: pending chunks only match lookups there.
    -- Committed chunks are found through the versions referencing them (see
    -- namespace). SET NULL if that library goes; versions elsewhere may still use it.
    library bigint,
    hash bytea NOT NULL CHECK (length(hash) = 16),
    -- TRIGGER: the storage is shared (NULL organization) or the chunk's organization's.
    storage bigint NOT NULL REFERENCES storage,
    -- Declared by the client at lookup: size before compression (and encryption).
    plain_size bigint NOT NULL CONSTRAINT chunk_plain_size CHECK (plain_size BETWEEN 0 AND 8388608),
    -- Declared together at upload-urls (only for chunks actually uploaded), then
    -- fixed: the presigned URL signs stored_sha256, so the backend only accepts
    -- exactly these bytes. NULL: not declared yet.
    stored_size bigint,
    compression text CHECK (compression IN ('none', 'lz4')),
    stored_sha256 bytea CHECK (length(stored_sha256) = 32),
    -- The user who declared it (counts towards their pending uploads). NULL once
    -- they leave the organization.
    declared_by bigint,
    -- When the last presigned URL issued for this chunk expires (plus a margin):
    -- its object can't be deleted before, or a late upload would leak an object.
    url_expires_at timestamptz,
    uploaded_at timestamptz,  -- NULL = pending
    touched_at timestamptz NOT NULL DEFAULT now(),
    deleting_at timestamptz,  -- GC tombstone
    -- Usable in a version: announced and not tombstoned. Target of chunk_in_version's
    -- FK, so a version can't reference a pending or tombstoned chunk, and a chunk
    -- still referenced by a version can't be tombstoned.
    ready boolean NOT NULL GENERATED ALWAYS AS (uploaded_at IS NOT NULL AND deleting_at IS NULL) STORED,
    UNIQUE (organization, pk, ready),
    FOREIGN KEY (organization, library) REFERENCES library (owner, pk) ON DELETE SET NULL (library),
    FOREIGN KEY (organization, declared_by) REFERENCES "user" (organization, pk) ON DELETE SET NULL (declared_by),
    -- Pending (all NULL) or announced (all set).
    -- The declaration is all or nothing.
    CONSTRAINT chunk_declared CHECK (
        (stored_size IS NULL) = (compression IS NULL) AND (stored_size IS NULL) = (stored_sha256 IS NULL)
    ),
    -- Compression never makes a chunk bigger (E2EE will relax this for its overhead).
    CONSTRAINT chunk_stored_size CHECK (stored_size BETWEEN 0 AND plain_size),
    -- An uploaded chunk was declared.
    CONSTRAINT chunk_uploaded_declared CHECK (uploaded_at IS NULL OR stored_size IS NOT NULL)
);
-- Lookups: by hash within an organization.
CREATE INDEX chunk_hash ON chunk (organization, hash);
-- A user's uploads in progress (max_pending_uploads).
CREATE INDEX chunk_declared_by ON chunk (declared_by) WHERE uploaded_at IS NULL AND declared_by IS NOT NULL;

-- chunk_in_version : version, chunk, position (UNIQUE(version, position))
CREATE TABLE chunk_in_version (
    pk bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    uuid uuid NOT NULL UNIQUE DEFAULT uuidv7(),
    organization bigint NOT NULL,
    version bigint NOT NULL,
    chunk bigint NOT NULL,
    -- Constant, only for the composite FK below: the chunk is ready.
    chunk_ready boolean NOT NULL DEFAULT true CHECK (chunk_ready),
    position integer NOT NULL CHECK (position >= 0),
    UNIQUE (version, position),
    CONSTRAINT chunk_in_version_version FOREIGN KEY (organization, version) REFERENCES version (organization, pk),
    -- Same organization as the version, and ready.
    CONSTRAINT chunk_in_version_chunk FOREIGN KEY (organization, chunk, chunk_ready) REFERENCES chunk (organization, pk, ready)
);
-- Dedup lookups and GC: which versions reference a chunk.
CREATE INDEX chunk_in_version_chunk ON chunk_in_version (chunk);

-- job_run : job, started_at, finished_at, status, items, error
CREATE TABLE job_run (
    pk bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    uuid uuid NOT NULL UNIQUE DEFAULT uuidv7(),
    job text NOT NULL,
    started_at timestamptz NOT NULL DEFAULT now(),
    finished_at timestamptz,
    status text NOT NULL DEFAULT 'running'
        CHECK (status IN ('running', 'success', 'failure', 'interrupted')),
    items integer NOT NULL DEFAULT 0 CHECK (items >= 0),
    error text,
    CONSTRAINT job_run_finished CHECK ((status = 'running') = (finished_at IS NULL)),
    CONSTRAINT job_run_failure_error CHECK (status <> 'failure' OR error IS NOT NULL)
);

-- email : recipient, template, params (json), attempts, next_attempt_at, sent_at, last_error
CREATE TABLE email (
    pk bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    uuid uuid NOT NULL UNIQUE DEFAULT uuidv7(),
    recipient text NOT NULL,
    template text NOT NULL,
    params jsonb NOT NULL,
    attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    sent_at timestamptz,
    -- Given up after the last attempt (last_error says why).
    given_up_at timestamptz,
    last_error text,
    CONSTRAINT email_done CHECK (sent_at IS NULL OR given_up_at IS NULL)
);
-- The sending job's queue.
CREATE INDEX email_due ON email (next_attempt_at) WHERE sent_at IS NULL AND given_up_at IS NULL;

-- setting : key, value
CREATE TABLE setting (
    key text PRIMARY KEY,
    value text NOT NULL
);

-- Triggers: invariants no constraint or composite FK can express.
-- They raise check_violation with a constraint name, like a CHECK would.

-- 1-3. A storage reserved to an organization only ever holds that organization's
-- data: a library, an organization's default and a chunk may only use a shared
-- storage (organization IS NULL) or one of their own organization.
CREATE FUNCTION check_storage_organization(storage_pk bigint, org bigint, constraint_name text)
RETURNS void LANGUAGE plpgsql AS $$
DECLARE
    storage_org bigint;
BEGIN
    SELECT organization INTO storage_org FROM storage WHERE pk = storage_pk;
    IF storage_org IS NOT NULL AND storage_org <> org THEN
        RAISE EXCEPTION 'storage % belongs to another organization', storage_pk
            USING ERRCODE = 'check_violation', CONSTRAINT = constraint_name;
    END IF;
END;
$$;

CREATE FUNCTION library_storage_organization() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    PERFORM check_storage_organization(NEW.storage, NEW.owner, 'library_storage_organization');
    RETURN NEW;
END;
$$;
CREATE TRIGGER library_storage_organization
    BEFORE INSERT OR UPDATE OF storage, owner ON library
    FOR EACH ROW EXECUTE FUNCTION library_storage_organization();

CREATE FUNCTION organization_default_storage() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.default_storage IS NOT NULL THEN
        PERFORM check_storage_organization(NEW.default_storage, NEW.pk, 'organization_default_storage');
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER organization_default_storage
    BEFORE INSERT OR UPDATE OF default_storage ON organization
    FOR EACH ROW EXECUTE FUNCTION organization_default_storage();

CREATE FUNCTION chunk_storage_organization() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    PERFORM check_storage_organization(NEW.storage, NEW.organization, 'chunk_storage_organization');
    RETURN NEW;
END;
$$;
CREATE TRIGGER chunk_storage_organization
    BEFORE INSERT OR UPDATE OF storage, organization ON chunk
    FOR EACH ROW EXECUTE FUNCTION chunk_storage_organization();

-- 4. A storage's organization is set at creation and never changes (in either
-- direction: reserving a shared storage would strand other organizations' data,
-- sharing a reserved one would expose it). This is also what keeps 1-3 true.
CREATE FUNCTION storage_organization_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.organization IS DISTINCT FROM OLD.organization THEN
        RAISE EXCEPTION 'the organization of storage % cannot change', OLD.pk
            USING ERRCODE = 'check_violation', CONSTRAINT = 'storage_organization_immutable';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER storage_organization_immutable
    BEFORE UPDATE OF organization ON storage
    FOR EACH ROW EXECUTE FUNCTION storage_organization_immutable();

-- 5. Moving a node never makes it its own ancestor. Inserts can't create a
-- cycle (a new node has no descendants), so only moves are checked: climb from
-- the new parent to the root, and refuse if the moved node is met. The cost is
-- the depth of the destination, not the size of the tree.
--
-- Concurrency: two moves "A under B" and "B under A" could each pass their check
-- and together create a cycle. So a move first locks its library row with
-- FOR NO KEY UPDATE: moves within a library run one after another, and the
-- second climb (a fresh snapshot, as each statement of a plpgsql function gets
-- in READ COMMITTED) sees the first move. Node inserts only take KEY SHARE on
-- the library (through their FK) and aren't blocked; nor are reads, or moves in
-- other libraries.
CREATE FUNCTION node_no_cycle() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    PERFORM 1 FROM library WHERE pk = NEW.library FOR NO KEY UPDATE;
    IF EXISTS (
        -- UNION (not UNION ALL): stops even if a cycle somehow existed already.
        WITH RECURSIVE ancestor (pk) AS (
            SELECT NEW.parent
            UNION
            SELECT n.parent FROM node n JOIN ancestor a ON n.pk = a.pk WHERE n.parent IS NOT NULL
        )
        SELECT 1 FROM ancestor WHERE pk = NEW.pk
    ) THEN
        RAISE EXCEPTION 'node % cannot be moved into its own subtree', NEW.pk
            USING ERRCODE = 'check_violation', CONSTRAINT = 'node_no_cycle';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER node_no_cycle
    BEFORE UPDATE OF parent ON node
    FOR EACH ROW WHEN (NEW.parent IS DISTINCT FROM OLD.parent AND NEW.parent IS NOT NULL)
    EXECUTE FUNCTION node_no_cycle();

-- 6. A member leaving an organization loses the identities they logged in
-- with through that organization's providers: the organization no longer
-- vouches for them. (Its restricted sessions already reach nothing: access
-- requires a joined membership.)
CREATE FUNCTION user_left_identities() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    DELETE FROM identity i USING identity_provider p
    WHERE i.account = OLD.account AND i.provider = p.pk AND p.organization = OLD.organization;
    RETURN OLD;
END;
$$;
CREATE TRIGGER user_left_identities
    AFTER DELETE ON "user"
    FOR EACH ROW EXECUTE FUNCTION user_left_identities();

-- 7. A personal organization never has another member than its account.
CREATE FUNCTION user_personal_organization() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM organization WHERE pk = NEW.organization AND personal_of <> NEW.account
    ) THEN
        RAISE EXCEPTION 'organization % is personal', NEW.organization
            USING ERRCODE = 'check_violation', CONSTRAINT = 'personal_organization';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER user_personal_organization
    BEFORE INSERT OR UPDATE OF account, organization ON "user"
    FOR EACH ROW EXECUTE FUNCTION user_personal_organization();
